
% ======================================================================= %
%                                                                         %
% This script plots the monthly and annual distribution of the data used  %
% to force SLAMS. The data array has been generated by previously running %
% the script createSlamsInputData.m.                                      %
%                                                                         %
%   Version 1.0 - Completed 10 Jan 2026                                 %
%                                                                         %
% ======================================================================= %

close all; clear all; clc
addpath(genpath(fullfile('.','modelresources','external')))
addpath(fullfile('.','modelresources','internal')) 
addpath(fullfile('.','data','processed')) 
addpath(fullfile('.','code','matlab')) 
addpath('figures');

% =========================================================================
%%
% -------------------------------------------------------------------------
% SECTION 1 - PRESETS (CHANGE ACCORDINGLY)
% -------------------------------------------------------------------------

% Name of experiment (change accordingly)
testrunDir = 'GLOBALSTD';
figureSubfolder = 'GLOBALSTD';

% Choices to be applied (change accordingly)
choiceTypeGridDomain = 1; % 1=global, 2=local, 3=global with zoom in factor
choicePar0level = 0;      % 1=zeu calculated as 1% PAR0, 0=zeu calculated as 0.1% PAR0
choiceTargetDepth = 100;   % m (target depth for mapping in this script)

% =========================================================================
%%
% -------------------------------------------------------------------------
% SECTION 2 - PRESETS (DO NOT CHANGE)
% -------------------------------------------------------------------------

% Directories
filenameInputForcing        = 'slamsForcing.mat';
filenameInputRunGrid        = 'grid_run.mat';
filenameInputNumDepthLayers = 'waterColNumDepthLayers.txt';
filenameOutputGeoForcing    = 'slamsForcingGeo.mat';

% Path declarations
fullpathTestDir             = fullfile('.','tests',testrunDir);
fullpathModelInputDataDir   = fullfile(fullpathTestDir,'modelinputdata');

% Load configuration parameters used in the model
config = loadModelConfigurationParameters(fullpathModelInputDataDir,...
    filenameInputRunGrid,filenameInputNumDepthLayers,choiceTypeGridDomain);

% =========================================================================
%%
% -------------------------------------------------------------------------
% SECTION 3 - LOAD INPUT DATA ARRAY
% -------------------------------------------------------------------------

% Generated by createSlamsInputData.m
load(fullfile(fullpathModelInputDataDir,filenameInputForcing),'mapStruct'); 

% =========================================================================
%%
% -------------------------------------------------------------------------
% SECTION 4 - CALCULATE PFT DATA AND LIGHT PROPERTIES USING THE SUBROUTINE 
% THAT SEEDS PHYTOPLANKTON FUNCTIONAL TYPES IN SLAMS
% -------------------------------------------------------------------------

[monthlyProbPft,monthlyMuPft,monthlyPar0,monthlyZeu] = calculatePftData(...
    mapStruct,choicePar0level,config);

% =========================================================================
%%
% -------------------------------------------------------------------------
% SECTION 5 - ORGANISE ALL INPUT DATA FOR MAPPING
% -------------------------------------------------------------------------

% Organise input data into a structure
monthlyData = struct( ...
    'Mesozoo', mapStruct.monthlyMesozoo, ...
    'Nit', mapStruct.monthlyNit, ...
    'Sil', mapStruct.monthlySil, ...
    'Phos', mapStruct.monthlyPhos, ...
    'Oxy', mapStruct.monthlyOxy, ...
    'Temp', mapStruct.monthlyTemp, ...
    'Rho', mapStruct.monthlyRho, ...
    'Omegac', mapStruct.monthlyOmegaC, ...
    'Chla', mapStruct.monthlyChla, ...
    'Dust', mapStruct.monthlyDust, ...
    'Mld', mapStruct.monthlyMld, ...
    'Npp', mapStruct.monthlyNpp, ...
    'Par0', monthlyPar0, ...
    'Zeu', monthlyZeu, ...
    'DynVisco', mapStruct.monthlyDynVisco, ...
    'ProbPft', monthlyProbPft,...
    'MuPft', monthlyMuPft);

% =========================================================================
%%
% -------------------------------------------------------------------------
% SECTION 6 - CALCULATE ANNUAL AVERAGES
% -------------------------------------------------------------------------

annualData = struct();
fields = fieldnames(monthlyData);
for iField = 1:length(fields)
    fieldName = fields{iField};
    annualData.(fieldName) = calculateAnnualAverage(monthlyData.(fieldName));
end

waterRho = annualData.Rho(1:20,:);
waterDynVisco = annualData.DynVisco(1:20,:);
meanWaterRho = nanmean(waterRho(:));
meanDynVisco = nanmean(waterDynVisco(:));

% =========================================================================
%%
% -------------------------------------------------------------------------
% SECTION 7 - REPOSITION DATA FROM LOCATION SEQUENCE TO LAT X LON ARRAY
% -------------------------------------------------------------------------

forcingDataGeo = struct();

% Determine the dimensions of geoData fields based on the type of data 
% (depth-dependent, PFT, or surface ocean)
for iField = 1:length(fields)
    fieldName = fields{iField};
    [annualSize,monthlySize] = getArrayDataSize(annualData.(fieldName),config.nLats,config.nLons);
    forcingDataGeo.(['annual' fieldName]) = NaN(annualSize);
    forcingDataGeo.(['monthly' fieldName]) = NaN(monthlySize);
end

% Loop over locations and populate geoData
for iLoc = 1:config.nLocs
    iLat = config.iyBb(iLoc);
    iLon = config.ixBb(iLoc);
    
    for iField = 1:length(fields)
        fieldName = fields{iField};

        if size(annualData.(fieldName),1) > 12 % depth-dependent data
            forcingDataGeo.(['annual' fieldName])(iLat,iLon,:) = annualData.(fieldName)(:,iLoc);
            forcingDataGeo.(['monthly' fieldName])(iLat,iLon,:,:) = monthlyData.(fieldName)(:,:,iLoc);
        elseif size(annualData.(fieldName),1) == 4 % PFT data
            forcingDataGeo.(['annual' fieldName])(iLat,iLon,:) = annualData.(fieldName)(:,iLoc);
            forcingDataGeo.(['monthly' fieldName])(iLat,iLon,:,:) = monthlyData.(fieldName)(:,:,iLoc);   
        else % surface ocean data
            forcingDataGeo.(['annual' fieldName])(iLat,iLon) = annualData.(fieldName)(iLoc);
            forcingDataGeo.(['monthly' fieldName])(iLat,iLon,:) = monthlyData.(fieldName)(:,iLoc);    
        end

    end
end

% Save for use in other functions
save(fullfile(fullpathModelInputDataDir,filenameOutputGeoForcing),'forcingDataGeo','-v7.3')

% =========================================================================
%%
% -------------------------------------------------------------------------
% SECTION 8 - PLOT GLOBAL MAPS WITH PFT PROPERTIES AND ENVIRONMENTAL FORCING 
% FOR SLAMS 
% -------------------------------------------------------------------------

% Datasets metadata (in this order to plot)
datasetsMetadata = { % all data already comes lat x lon
    'Npp',      sprintf('Depth-integrated NPP,\n ESA-BICEP'),                     'mg C m^{-2} d^{-1}',    'algae',    0,    900, false, true,  3600*24*config.molarMassCarbon*1e3; % mol C m-2 s-1 --> mg C m-2 d-1 
    'Mesozoo',  sprintf('Mesozooplankton biomass in the upper 200 m,\n CMIP6-PISCES'),               'mg C m^{-2}',           'matter',   0,    900, false, false, NaN; 
