    'Chla',     sprintf('Depth-integrated Chla concentration,\n ESA-OCCCI'),                'mg m^{-3}',             'algae',    0,      1, false, false, NaN; 
    'Par0',     sprintf('Surface PAR,\n NASA-MODIS'),                 'W m^{-2}',              'solar',    20,    130, false, false, NaN;
    'Mld',      sprintf('MLD,\n IFREMER/LOPS'),                                        'm',                     'deep',     20,    170, false, false, NaN; 
    'Temp',     sprintf('Temperature at %d m\n WOA23',choiceTargetDepth),                            'ºC',                    'thermal', 0,     28, true,  false, NaN; 
    'Rho',      sprintf('Density at %d m,\n calculated from WOA23',choiceTargetDepth),               'g cm^{-3}',             'dense', 1.022, 1.028, true,  false, NaN;
    'DynVisco', sprintf('Dynamic viscosity at %d m,\n calculated from WOA23',choiceTargetDepth),     'g cm^{-1} s^{-1}',      'ice',   0.009, 0.017, true,  false, NaN; 
    'Nit',      sprintf('Nitrate concentration at %d m,\n WOA23',choiceTargetDepth),                 'mmol m^{-3}',           'haline',   0,     30, true,  false, NaN;        
    'Sil',      sprintf('Silicate concentration at %d m,\n WOA23',choiceTargetDepth),                'mmol m^{-3}',           'haline',   0,     50, true,  false, NaN;  
