% LOCAL FUNCTIONS
% -------------------------------------------------------------------------

function [monthlyProbPft,monthlyMuPft,monthlyPar0,monthlyZeu] =...
    calculatePftData(mapStruct,choicePar0level,config)

    % This function is as PhytoSeedingProbabilities in primaryproduction.F90

    % Precompute avgPar0 for each location
    % Calculate daily mean PAR0 for an average day in a month
    monthlyPar0 = NaN(12,config.nLocs);
    for iLoc = 1:config.nLocs
        addPar0 = zeros(12,1);
        iMonth = 1;

        for iDay = 1:365
            dailyPar0daylight = mapStruct.dailyPar0daylight(iDay, iLoc);
            if isnan(dailyPar0daylight)
                dailyPar0daylight = 0; % replace NaN with 0 so that it can be summed
            end
            addPar0(iMonth) = addPar0(iMonth) + dailyPar0daylight;      
            if (mod(iDay,config.julianDayInMonth(iMonth)) == 0)
                iMonth = iMonth + 1;
            end         
        end

        monthlyPar0(:,iLoc) = addPar0 ./ config.nDaysPerMonth';
    end

    % Initialise output arrays
    monthlyProbPft = NaN(4,12,config.nLocs); % frac
    monthlyMuPft   = NaN(4,12,config.nLocs); % d-1
    monthlyZeu     = NaN(12,config.nLocs); % m

    for iLoc = 1:config.nLocs

        % Calculate depth layers
        nValidDepthLayers = sum(~isnan(config.gridDepths(:,iLoc))); % count valid depth layers
        localDepths = config.gridDepths(1:nValidDepthLayers,iLoc); % extract valid depths

        forcProbPft = NaN(4,12);
        forcMuPft   = NaN(4,12);
        
        for iMonth = 1:12

            % Skip processing for months with no light, no chla or no MLD
            if monthlyPar0(iMonth,iLoc) <= 0 ||...
                isnan(mapStruct.monthlyChla(iMonth,iLoc)) || ...
                isnan(mapStruct.monthlyMld(iMonth,iLoc))
                continue;
            end

            % Calculate zeu (depth where PARz > 1% of PAR0)
            [zeu,kpar] = calculateZeuFromChlaAndMLD(mapStruct.monthlyChla(iMonth,iLoc),...
                mapStruct.monthlyMld(iMonth,iLoc),choicePar0level);
                
            % The above is equivalent to this other way I was using before
            parz = monthlyPar0(iMonth,iLoc).*exp(-kpar.*localDepths(:)); % W m-2 
            validDepthIdx = (parz ./ monthlyPar0(iMonth,iLoc)) >= 1e-3;
            nLocalDepthsToSeedPhyto = sum(validDepthIdx);

            if nLocalDepthsToSeedPhyto == 0
                monthlyZeu(iMonth,iLoc) = 0;
                continue;
            end

            % Process phytoplankton growth at valid depths
            validNit = mapStruct.monthlyNit(validDepthIdx,iMonth,iLoc);
            validNpp = mapStruct.monthlyNpp(iMonth,iLoc);

            if any(validNit > 0) && validNpp > 0
                [muLimFactorPft(:,validDepthIdx), muNetPft(:,validDepthIdx), chlToCarbonPft(:,validDepthIdx)] = ...
                    calculatePhytoGrowthRate(...
                        mapStruct.monthlyNit(validDepthIdx,iMonth,iLoc), ...
                        mapStruct.monthlySil(validDepthIdx,iMonth,iLoc), ...
                        mapStruct.monthlyPhos(validDepthIdx,iMonth,iLoc), ...
                        mapStruct.monthlyTemp(validDepthIdx,iMonth,iLoc), ...
                        parz(validDepthIdx), config.pft.q10, config.pft.tempRef, ...
                        config.pft.muMax0degPft, config.pft.kNO3Pft, ...
                        config.pft.kPO4Pft, config.pft.kSiDiat, config.pft.chlToCarbonMax, ...
                        config.pft.alphaChlSpecificPft, config.pft.muThreshold);
            else
                muLimFactorPft = NaN(4,nLocalDepthsToSeedPhyto);
                muNetPft = NaN(4,nLocalDepthsToSeedPhyto);
                chlToCarbonPft = NaN(4,nLocalDepthsToSeedPhyto);
            end

            % Store zeu value for the month and location
            monthlyZeu(iMonth,iLoc) = localDepths(nLocalDepthsToSeedPhyto);

            % Calculate probabilities of seeding for each PFT and depth
            muNetPftSum = sum(muNetPft,2,'omitnan'); % sum over depth layers for each PFT
            muNetTotal = sum(muNetPftSum,'omitnan');

            if muNetTotal > 0
                probPft = muNetPftSum ./ muNetTotal;
                probPftAtDepth = muNetPft ./ muNetPftSum;

                % Assign probabilities and growth rates
                forcProbPft(:,iMonth) = probPft;
                forcMuPft(:,iMonth) = mean(muNetPft(:,1:nLocalDepthsToSeedPhyto),2,'omitnan'); % d-1
            end

        end % iMonth

        % Store output for current location
        monthlyProbPft(:,:,iLoc) = forcProbPft;
        monthlyMuPft(:,:,iLoc) = forcMuPft;

    end % iLoc

    % NOTE: Cphyto cannot be calculated as NPP_phyto/mu_phyto (from 
    % NPP_phyto = mu_phyto x Cphyto). But we can calculate NPP_phyto 
    % (mg C m-2 d-1) and the relative abundance of each PFT will be the 
    % same as that shown by monthlyProbPft calculated from mu.

    % % Calculate Cphyto
    % 
    % addCarbon = zeros(4,12,config.nLocs);
    % for iLoc = 1:config.nLocs   
    %     for iMonth = 1:12
    %         amountCarbonPerSeedingEvent = nppMonthly(iMonth,iLoc).*(config.molarMassCarbon*1000*config.depthLayerArea*3600*24)/20; % mol C m-2 s-1 --> mg C 
    %         if (sum(probPftMonthly(:,iMonth,iLoc)) > 0)
    %             for iSeedingEvent = 1:20
    %                 iPft = randsample(1:4, 1, true, squeeze(monthlyProbPft(:,iMonth,iLoc)));
    %                 addCarbon(iPft,iMonth,iLoc) = addCarbon(iPft,iMonth,iLoc) + amountCarbonPerSeedingEvent; % mg C
    %             end
    %         end
    %     end
    % end
    % 
    % monthlyNppPhyto = addCarbon./(config.depthLayerArea*3600*24); % mg C --> mg C m-2 s-1
    % 
    % monthlyCphyto = zeros(4,12,config.nLocs);
    % for iLoc = 1:config.nLocs
    %     for iMonth = 1:12
    %         for iPft = 1:4
    %             pftGrowthRate = monthlyMuPft(iPft,iMonth,iLoc)./(3600*24); % s-1
    %             monthlyCphyto(iPft,iMonth,iLoc) = monthlyNppPhyto(iPft,iMonth,iLoc)/(monthlyZeu(iMonth,iLoc)*pftGrowthRate); % mg C m-3
    %         end
    %     end
    % end
    % monthlyCphyto(isnan(monthlyCphyto)) = 0;

end % calculatePftData

% *************************************************************************

function annualField = calculateAnnualAverage(fieldData)
   
    if size(fieldData, 1) > 12
        % Depth-dependent data
        annualField = squeeze(mean(fieldData, 2, 'omitnan'));
    elseif size(fieldData, 1) == 4
        % PFT data
        annualField = squeeze(mean(fieldData, 2, 'omitnan'));
    else
        % Surface ocean data
        annualField = squeeze(mean(fieldData, 1, 'omitnan'));
    end
    
end % calculateAnnualAverage

% *************************************************************************

function [annualSize,monthlySize] = getArrayDataSize(fieldData,nLats,nLons)

    if size(fieldData, 1) > 12
        % Depth-dependent data
        annualSize = [nLats, nLons, size(fieldData,1)];
        monthlySize = [nLats, nLons, size(fieldData,1), 12];
    elseif size(fieldData, 1) == 4
        % PFT data
        annualSize = [nLats, nLons, 4];
        monthlySize = [nLats, nLons, 4, 12];
    else
        % Surface ocean data
        annualSize = [nLats, nLons];
        monthlySize = [nLats, nLons, 12];
    end
    
end % getArrayDataSize
     
% *************************************************************************        

function plotEnvironmentalForcing(figureSubfolderName,figurePrefixName,...
    forcingDataGeo,datasetsMetadata,choiceTargetDepth,config)


    [~,idxTargetDepth] = min(abs(config.gridDepths(:,1) - choiceTargetDepth));

    annualMeanData = NaN(config.nLats,config.nLons,length(datasetsMetadata));
    monthlyMeanData = NaN(config.nLats,config.nLons,12,length(datasetsMetadata));
    
    cbString = cell(length(datasetsMetadata),1); 
    cbPalette = cell(length(datasetsMetadata),1);
    caxisMin = zeros(length(datasetsMetadata),1);
    caxisMax = zeros(length(datasetsMetadata),1);
    
    for iTimescale = 1:2
        switch iTimescale
            case 1
                timeScale = 'monthly';
            case 2
                timeScale = 'annual';
        end
        for iDataset = 1:height(datasetsMetadata)
            baseFieldName = datasetsMetadata{iDataset,1};
            hasDepth = datasetsMetadata{iDataset,7};
            needsConversion = datasetsMetadata{iDataset,8};
            unitsFactor = datasetsMetadata{iDataset,9};

            % Construct dynamic field name
            fieldName = [timeScale baseFieldName];
            if isfield(forcingDataGeo, fieldName)
                varValue = forcingDataGeo.(fieldName);
            end

            % Integrate Mesozoo if required
            if contains(baseFieldName,'Mesozoo')
                % Zooplankton: integrate over depth using trapezoidal integration
                 varValue = integrateOverDepth(varValue,config); % mg C m-3 --> mg C m-2
            end
            % Apply unit conversion if needed
            if needsConversion
                varValue = varValue.*unitsFactor;
            end
            % Extract the slice at target depth if applicable
            if hasDepth
                if ndims(varValue) == 3
                    % Annual: lat x lon x depth
                    varValue = squeeze(varValue(:,:,idxTargetDepth));
                elseif ndims(varValue) == 4
                    % Monthly: lat x lon x depth x time (months)
                    varValue = squeeze(varValue(:,:,idxTargetDepth,:));
                end
            end

            % Check if the data spans multiple orders of magnitude (log10 values) and 
            % decide whether to apply a log10 transformation.
            caxisMin(iDataset) = cell2mat(datasetsMetadata(iDataset,5));
            caxisMax(iDataset) = cell2mat(datasetsMetadata(iDataset,6));
            cbPalette{iDataset} = cmocean(datasetsMetadata{iDataset,4});
            cbString{iDataset} = datasetsMetadata{iDataset,3};  
            orderMin = log10(caxisMin(iDataset));
            if caxisMin(iDataset) == 0
                orderMin = 0;
            end
            orderMax = log10(caxisMax(iDataset));
            if (max(orderMax,orderMin) - min(orderMax,orderMin)) >= 3 % if the difference in orders of magnitude >= 4
                varValue = log10(varValue);
                caxisMin(iDataset) = log10(caxisMin(iDataset));
                caxisMax(iDataset) = log10(caxisMax(iDataset));
                cbString{iDataset} = [cbString{iDataset}, ' (log10)'];
            end
              
            switch iTimescale
                case 1
                    monthlyMeanData(:,:,:,iDataset) = varValue;
                case 2
                    annualMeanData(:,:,iDataset) = varValue;
            end
        end % iDataset
    end % iTimescale

    % Plot the annual mean data using the custom plotting function
    isCommonColourBar = false;
    % for iDataset = 1:height(datasetsMetadata)
    %     datasetName = lower(datasetsMetadata{iDataset,1});
    %     sgTitle = datasetsMetadata(iDataset,2);
    %     titleStr = config.mappingProps.labelMonths;
    %     plotOceanVariableMaps(monthlyMeanData(:,:,:,iDataset),...
    %         config.mappingProps.mapLons,config.mappingProps.mapLats,...
    %         cbPalette{iDataset},cbString{iDataset},caxisMin(iDataset),...
    %         caxisMax(iDataset),isCommonColourBar,titleStr,...
    %         strcat(figurePrefixName,'_monthly_',datasetName),figureSubfolderName,sgTitle)
    % end

    titleStr = datasetsMetadata(:,2);
    plotOceanVariableMaps(annualMeanData,config.mappingProps.mapLons,...
        config.mappingProps.mapLats,cbPalette,cbString,caxisMin,caxisMax,isCommonColourBar,...
        titleStr,strcat(figurePrefixName,'_annual'),figureSubfolderName,[])

end % plotEnvironmentalForcing

