function plotGrowthRatePfts(figureSubfolderName,figurePrefixName,annualMuPft,...
    monthlyMuPft,config)

    cbString = 'Growth rate (d^{-1})';
    caxisMin = 0;
    caxisMax = 0.7;
    isCommonColourBar = 1;

    for iFigure = 1:3

        if (iFigure == 1)

            oceanVar = annualMuPft;
            plotOceanVariableMaps(oceanVar,config.mappingProps.mapLons,config.mappingProps.mapLats,...
                config.mappingProps.myColourMapOceanVars,cbString,caxisMin,caxisMax,...
                isCommonColourBar,config.mappingProps.labelFourPfts,figurePrefixName,...
                figureSubfolderName,[])

        elseif (iFigure == 2)

            for iPft = 1:4
                oceanVar = squeeze(monthlyMuPft(:,:,iPft,:));
                plotOceanVariableMaps(oceanVar,config.mappingProps.mapLons,...
                    config.mappingProps.mapLats,config.mappingProps.myColourMapOceanVars,...
                    cbString,caxisMin,caxisMax,isCommonColourBar,config.mappingProps.labelMonths,...
                    strcat(figurePrefixName,'_bymonth_',num2str(iPft)),...
                    figureSubfolderName,config.mappingProps.labelFourPfts(iPft))
            end
        end

    end % iFigure

end % plotGrowthRatePfts

